<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller;use App\Http\Requests\Api\MachineRequest;use App\Http\Resources\MachineResource;use App\Models\Machine;use App\Repositories\MachineRepository;use App\Services\CrudService;
class MachineController extends Controller {private CrudService $service;public function __construct(MachineRepository $r){$this->service=new CrudService($r);}public function index(){return MachineResource::collection($this->service->all(['controllers.devices']));}public function store(MachineRequest $r){return (new MachineResource($this->service->create($r->validated())))->response()->setStatusCode(201);}public function show(Machine $machine){return new MachineResource($machine->load('controllers.devices'));}public function update(MachineRequest $r,Machine $machine){return new MachineResource($this->service->update($machine,$r->validated()));}public function destroy(Machine $machine){$this->service->delete($machine);return response()->noContent();}}
